-- 커리큘럼 감사(2026-11-19) 반영: 단원 40개의 세트 표시 순서를 개념 의존 순서(계단식 누적)로 바꾼다.
-- 단원이 현재 쓰는 display_order 자리(오름차순)를 제안 순서대로 다시 나눠 주므로 다른 단원의 위치는 그대로다. 같은 SQL 을 다시 실행해도 결과가 같다.
-- 근거와 단원별 비교: docs/research/curriculum_reorder_review_2026-11-19.md

-- [리눅스] 기초 (단원 1, 이동 6/10)
UPDATE quest_set t JOIN (SELECT p.id, a.slot FROM (SELECT 1 AS pos, 42 AS id UNION ALL SELECT 2 AS pos, 43 AS id UNION ALL SELECT 3 AS pos, 1 AS id UNION ALL SELECT 4 AS pos, 2 AS id UNION ALL SELECT 5 AS pos, 45 AS id UNION ALL SELECT 6 AS pos, 34 AS id UNION ALL SELECT 7 AS pos, 65 AS id UNION ALL SELECT 8 AS pos, 3 AS id UNION ALL SELECT 9 AS pos, 85 AS id UNION ALL SELECT 10 AS pos, 21 AS id) p JOIN (SELECT ROW_NUMBER() OVER (ORDER BY display_order, id) AS rn, display_order AS slot FROM quest_set WHERE id IN (42,43,1,2,45,34,65,3,85,21)) a ON a.rn = p.pos) m ON m.id = t.id SET t.display_order = m.slot;

